import { computed, onMounted, onBeforeUnmount, ref } from 'vue'
import {
  useInfra, TABS, fmtTime, fmtBytes, tone
} from './useInfra'
import {
  monitoring, MONITORING_TAB, REFRESH_INTERVALS,
  startMonitoring, stopMonitoring, setLive, setRefreshInterval
} from './useInfraMonitor'
import { layout, observePanelWidth } from './useInfraLayout'
import MonitoringPanel from './MonitoringPanel.vue'
import ContainersPanel from './ContainersPanel.vue'
import ContainerDrawer from './ContainerDrawer.vue'
import HostSettingsModal from './HostSettingsModal.vue'
import CloudServerModal from './CloudServerModal.vue'
import StacksPanel from './StacksPanel.vue'
import ImagesPanel from './ImagesPanel.vue'
import VolumesPanel from './VolumesPanel.vue'
import NetworksPanel from './NetworksPanel.vue'
import EventsPanel from './EventsPanel.vue'
import MaintenancePanel from './MaintenancePanel.vue'

const {
  state, filteredList, tabCount,
  loadHosts, selectedHost, openHostModal, openHostSettings, openCloudModal,
  loadAll, setRoute, setHost, setFilter,
  openRunModal, submitRun, updateRunField
} = useInfra()

/**
 * Tab strip.
 *
 * The monitoring overview is prepended because it is the "is anything on fire?"
 * answer, but `state.route` still defaults to `containers`, so the view keeps
 * opening exactly where it always did.
 */
const tabs = [MONITORING_TAB, ...TABS]

/* ── panel width tracking (this view lives in a resizable dockview panel) ─── */
const rootEl = ref(null)
let disposeLayout = null

/* ── derived ──────────────────────────────────────────────────────────────── */
const counts = computed(() => state.summary?.counts || {
  total: 0, running: 0, stopped: 0, paused: 0, restarting: 0, unhealthy: 0, images: 0, volumes: 0, networks: 0
})

const memPct = computed(() => {
  const s = state.summary
  return s ? Math.round((s.mem_used / s.mem_total) * 100) : 0
})
const diskPct = computed(() => {
  const s = state.summary
  return s ? Math.round((s.disk_used / s.disk_total) * 100) : 0
})

/** Tooltip for the selector: what the selected host actually points at. */
const hostSummary = computed(() => {
  const host = selectedHost.value
  if (!host) return 'No Docker host registered yet'
  const parts = [host.endpoint]
  if (host.kind === 'ssh' && host.hostname) parts.push(`ssh ${host.ssh_user ? host.ssh_user + '@' : ''}${host.hostname}:${host.ssh_port}`)
  if (host.ssh_key_id) parts.push(`key ${host.ssh_key_id}`)
  if (host.provider) parts.push(`${host.provider}${host.region ? ' · ' + host.region : ''}`)
  if (host.engine) parts.push(`engine ${host.engine}`)
  return parts.filter(Boolean).join(' · ')
})

const searchPlaceholder = computed(() => ({
  containers: 'Search by name, image, service, stack…',
  stacks: 'Search stacks…',
  images: 'Search repository or tag…',
  volumes: 'Search volumes…',
  networks: 'Search networks…',
  events: 'Filter events by actor…'
}[state.route] || 'Search…'))

/* ── helpers ──────────────────────────────────────────────────────────────── */
function onHostChange (e) { setHost(e.target.value) }
function reloadAll () { loadAll() }

function meterClass (toneName) {
  return { success: 'progress-success', warning: 'progress-warning', error: 'progress-error' }[toneName] || 'progress-primary'
}
function toastClass (kind) {
  return { success: 'alert-success', error: 'alert-error', warning: 'alert-warning' }[kind] || 'alert-info'
}
function toastIcon (kind) {
  return {
    success: 'fa-circle-check',
    error: 'fa-circle-xmark',
    warning: 'fa-triangle-exclamation'
  }[kind] || 'fa-circle-info'
}

/* ── lifecycle ────────────────────────────────────────────────────────────── */
onMounted(async () => {
  disposeLayout = observePanelWidth(rootEl.value)
  // 1. Hosts first — every other endpoint is scoped by the selected host id.
  await loadHosts()
  // 2. Then the host snapshot (loadAll re-uses the cached host list).
  await loadAll()
  // 3. Start sampling. Live is ON by default (5s), and the first snapshot
  //    already recorded one point, so the charts have something to draw.
  startMonitoring()
})
onBeforeUnmount(() => {
  if (disposeLayout) {
    disposeLayout()
    disposeLayout = null
  }
  // Stop polling when the view unmounts; the live/interval preference is kept
  // so the next mount resumes with the operator's choice.
  stopMonitoring()
})
</script>
